package com.pmtrack.controller; import com.pmtrack.dto.TaskDto; import com.pmtrack.model.User; import com.pmtrack.security.UserPrincipal; import com.pmtrack.service.TaskService; import com.pmtrack.service.UserService; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import org.springframework.http.ResponseEntity; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.List; import java.util.Map; @RestController @RequestMapping("/api/tasks") @Tag(name = "Tasks", description = "Task and Sub-task operations, Kanban updates, and comments") public class TaskController { private final TaskService taskService; private final UserService userService; public TaskController(TaskService taskService, UserService userService) { this.taskService = taskService; this.userService = userService; } @GetMapping @Operation(summary = "Get tasks assigned to or visible to current user") public ResponseEntity<List<TaskDto.TaskResponse>> getMyTasks(@AuthenticationPrincipal UserPrincipal userPrincipal) { User currentUser = userService.getUserEntityById(userPrincipal.getId()); return ResponseEntity.ok(taskService.getTasksForUser(currentUser)); } @GetMapping("/project/{projectId}") @Operation(summary = "Get all tasks for a specific project") public ResponseEntity<List<TaskDto.TaskResponse>> getTasksByProject( @PathVariable Long projectId, @AuthenticationPrincipal UserPrincipal userPrincipal) { User user = userService.getUserEntityById(userPrincipal.getId()); return ResponseEntity.ok(taskService.getTasksByProjectId(projectId, user)); } @GetMapping("/{id}") @Operation(summary = "Get task details by ID") public ResponseEntity<TaskDto.TaskResponse> getTaskById( @PathVariable Long id, @AuthenticationPrincipal UserPrincipal userPrincipal) { User user = userService.getUserEntityById(userPrincipal.getId()); return ResponseEntity.ok(taskService.getTaskById(id, user)); } @PostMapping @PreAuthorize("hasAnyRole('SUPER_ADMIN', 'ADMIN', 'PROJECT_MANAGER', 'TEAM_LEAD')") @Operation(summary = "Create a new task") public ResponseEntity<TaskDto.TaskResponse> createTask( @Valid @RequestBody TaskDto.TaskRequest request, @AuthenticationPrincipal UserPrincipal userPrincipal) { User creator = userService.getUserEntityById(userPrincipal.getId()); return ResponseEntity.ok(taskService.createTask(request, creator)); } @PutMapping("/{id}") @PreAuthorize("hasAnyRole('SUPER_ADMIN', 'ADMIN', 'PROJECT_MANAGER', 'TEAM_LEAD')") @Operation(summary = "Update task details") public ResponseEntity<TaskDto.TaskResponse> updateTask( @PathVariable Long id, @Valid @RequestBody TaskDto.TaskRequest request, @AuthenticationPrincipal UserPrincipal userPrincipal) { User modifier = userService.getUserEntityById(userPrincipal.getId()); return ResponseEntity.ok(taskService.updateTask(id, request, modifier)); } @PatchMapping("/{id}/status") @Operation(summary = "Update task status and progress (Kanban drag-drop or execution update)") public ResponseEntity<TaskDto.TaskResponse> updateStatus( @PathVariable Long id, @RequestBody TaskDto.StatusUpdateDto dto, @AuthenticationPrincipal UserPrincipal userPrincipal) { User modifier = userService.getUserEntityById(userPrincipal.getId()); return ResponseEntity.ok(taskService.updateTaskStatus(id, dto.getStatus(), dto.getProgressPercentage(), modifier)); } @PostMapping("/{id}/subtasks") @Operation(summary = "Add subtask to task") public ResponseEntity<TaskDto.SubTaskDto> addSubTask( @PathVariable Long id, @RequestBody Map<String, Object> payload, @AuthenticationPrincipal UserPrincipal userPrincipal) { String title = payload.get("title").toString(); Long assigneeId = payload.containsKey("assignedToId") && payload.get("assignedToId") != null ? Long.valueOf(payload.get("assignedToId").toString()) : null; User actor = userService.getUserEntityById(userPrincipal.getId()); return ResponseEntity.ok(taskService.addSubTask(id, title, assigneeId, actor)); } @PostMapping("/subtasks/{subTaskId}/toggle") @Operation(summary = "Toggle subtask completed status") public ResponseEntity<?> toggleSubTask( @PathVariable Long subTaskId, @AuthenticationPrincipal UserPrincipal userPrincipal) { User actor = userService.getUserEntityById(userPrincipal.getId()); taskService.toggleSubTask(subTaskId, actor); return ResponseEntity.ok(Map.of("message", "Subtask toggled successfully")); } @PostMapping("/{id}/comments") @Operation(summary = "Add comment to task") public ResponseEntity<TaskDto.TaskCommentDto> addComment( @PathVariable Long id, @RequestBody Map<String, String> payload, @AuthenticationPrincipal UserPrincipal userPrincipal) { User author = userService.getUserEntityById(userPrincipal.getId()); return ResponseEntity.ok(taskService.addComment(id, payload.get("content"), author)); } }
